      identifyWeakAreas(attempts) {
        const domainScores = {};
        for (const attempt of attempts) {
          const domain = "general";
          if (!domainScores[domain]) {
            domainScores[domain] = [];
          }
          domainScores[domain].push(attempt.score);
        }
        return Object.entries(domainScores).map(([domain, scores]) => ({
          domain,
          averageScore: scores.reduce((a, b) => a + b, 0) / scores.length
        })).filter((area) => area.averageScore < 60);
      }
      identifyStrongAreas(attempts) {
        const domainScores = {};
        for (const attempt of attempts) {
          const domain = "general";
          if (!domainScores[domain]) {
            domainScores[domain] = [];
          }
          domainScores[domain].push(attempt.score);
        }
        return Object.entries(domainScores).map(([domain, scores]) => ({
          domain,
          averageScore: scores.reduce((a, b) => a + b, 0) / scores.length
        })).filter((area) => area.averageScore >= 80);
      }
