  /**
   * Génère des recommandations basées sur les résultats de validation
   */
  generateRecommendations(results) {
    const recommendations = [];
    const failedTests = results.filter((r) => r.status === "fail");
    const warningTests = results.filter((r) => r.status === "warning");
    if (failedTests.length > 0) {
      recommendations.push(`${failedTests.length} test(s) critique(s) \xE9chou\xE9(s). Intervention imm\xE9diate requise.`);
      failedTests.forEach((test) => {
        recommendations.push(`- Corriger: ${test.component} - ${test.message}`);
      });
    }
    if (warningTests.length > 0) {
      recommendations.push(`${warningTests.length} avertissement(s) d\xE9tect\xE9(s). Surveillance recommand\xE9e.`);
    }
    const slowTests = results.filter((r) => r.executionTime > 5e3);
    if (slowTests.length > 0) {
      recommendations.push(`Tests lents d\xE9tect\xE9s: ${slowTests.map((t) => t.component).join(", ")}. Optimisation recommand\xE9e.`);
    }
    if (recommendations.length === 0) {
      recommendations.push("Syst\xE8me enti\xE8rement op\xE9rationnel. Aucune action imm\xE9diate requise.");
      recommendations.push("Continuer la surveillance r\xE9guli\xE8re des performances et de la s\xE9curit\xE9.");
    }
    return recommendations;
  }
